//! End to end on SQLite: a six-level chain and a diamond of `sql:` pipes, synced by the engine
//! over three phases of source changes, must leave the same tables as v4.1's `sync pipes -w 1`
//! (`tests/fixtures/v4_sync/v4_sync.json`, generated by `gen_v4_sync.py` next to it).
//!
//! Two variants replay the phases: a dependency-aware run (`--parents` over the two leaves) and
//! a flat lap (`sync pipes -w 1`, v4 semantics, R1).

mod common;

use common::*;
use meerschaum_engine::{Action, Depth, NodeStatus, RunOptions, Selection};

fn fixture() -> serde_json::Value {
    let text = include_str!("fixtures/v4_sync/v4_sync.json");
    serde_json::from_str(text).expect("valid fixture")
}

async fn setup(tag: &str) -> (Env, serde_json::Value) {
    let fx = fixture();
    let env = env(tag).await;
    env.exec(fx["create"].as_str().unwrap()).await;
    for p in fx["pipes"].as_array().unwrap() {
        env.register(p["metric"].as_str().unwrap(), &p["parameters"])
            .await;
    }
    (env, fx)
}

async fn assert_phase(env: &Env, fx: &serde_json::Value, phase: usize, variant: &str) {
    let expected = &fx["phases"][phase]["expected"];
    for p in fx["pipes"].as_array().unwrap() {
        let metric = p["metric"].as_str().unwrap();
        let want = Table::from_fixture(&expected[metric]);
        let got = env.table(metric).await;
        assert_eq!(
            got.columns, want.columns,
            "{variant}, phase {phase}: columns of {metric}"
        );
        if got.rows != want.rows {
            let missing: Vec<&String> =
                want.rows.iter().filter(|r| !got.rows.contains(r)).collect();
            let extra: Vec<&String> = got.rows.iter().filter(|r| !want.rows.contains(r)).collect();
            panic!(
                "{variant}, phase {phase}: {metric} differs from v4 ({} vs {} rows)\n\
                 missing: {missing:#?}\nextra: {extra:#?}",
                got.rows.len(),
                want.rows.len()
            );
        }
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn parents_run_matches_v4_sync_pipes() {
    let (env, fx) = setup("v4_parents").await;
    let engine = env.engine();
    let leaves = vec![env.pipe_ref("f_report"), env.pipe_ref("i_joined")];
    for (i, phase) in fx["phases"].as_array().unwrap().iter().enumerate() {
        for stmt in phase["statements"].as_array().unwrap() {
            env.exec(stmt.as_str().unwrap()).await;
        }
        let result = engine
            .run(RunOptions {
                selection: Some(Selection::refs(leaves.clone()).with_parents(Some(Depth::All))),
                ..Default::default()
            })
            .await;
        assert!(
            result.success,
            "phase {i}: {}\n{:#?}",
            result.message, result.outcomes
        );
        let record = result.record.as_ref().unwrap();
        assert_eq!(record.nodes.len(), 9);
        if i == 0 {
            // First engine run: nothing is skipped.
            assert!(
                record
                    .nodes
                    .iter()
                    .all(|n| n.status == NodeStatus::Succeeded),
                "{:#?}",
                record.nodes
            );
        }
        if i == 2 {
            // No source changes: only the root syncs; every child is skipped by its cursors.
            for n in &record.nodes {
                if n.pipe_ref == env.pipe_ref("a_raw") {
                    assert_eq!(n.action, Action::Root);
                    assert_eq!(n.status, NodeStatus::Succeeded);
                } else {
                    assert_eq!(n.status, NodeStatus::Skipped, "{n:#?}");
                }
            }
        }
        assert_phase(&env, &fx, i, "--parents").await;
    }

    // The run is persisted with its nodes and events.
    let run_id = engine
        .run(RunOptions {
            selection: Some(Selection::refs(leaves.clone()).with_parents(Some(Depth::All))),
            ..Default::default()
        })
        .await
        .run_id()
        .unwrap()
        .to_string();
    let loaded = engine.state().load_run(&run_id).await.unwrap().unwrap();
    assert_eq!(loaded.nodes.len(), 9);
    let events = engine.state().load_events(&run_id).await.unwrap();
    assert!(events.iter().any(|e| e.event == "run_started"));
    assert!(events.iter().any(|e| e.event == "run_finished"));
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn flat_lap_matches_v4_sync_pipes() {
    let (env, fx) = setup("v4_flat").await;
    let engine = env.engine();
    for (i, phase) in fx["phases"].as_array().unwrap().iter().enumerate() {
        for stmt in phase["statements"].as_array().unwrap() {
            env.exec(stmt.as_str().unwrap()).await;
        }
        let result = engine
            .run(RunOptions {
                workers: Some(1),
                ..Default::default()
            })
            .await;
        assert!(result.success, "phase {i}: {}", result.message);
        // `-w 1`: v4's order (sorted keys, `connectors/sql/_pipes.py:345`; also dependency order here).
        let order: Vec<String> = result
            .outcomes
            .iter()
            .map(|o| o.pipe_ref.parts().metric_key.to_string())
            .collect();
        let registered: Vec<String> = fx["pipes"]
            .as_array()
            .unwrap()
            .iter()
            .map(|p| p["metric"].as_str().unwrap().to_string())
            .collect();
        assert_eq!(order, registered, "phase {i}");
        assert!(result.outcomes.iter().all(|o| o.result.success));
        assert_phase(&env, &fx, i, "flat").await;
    }
}
